<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('commercial_manager');$user=current_user();$flashes=render_flashes();$currentPage='capability_packs';$pageTitle='Capability Packs';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);$rows=[];
if(cm_table($conn,'commercial_capability_packs')){$s=$conn->prepare("SELECT cp.id,cp.pack_name,cp.tender_reference,cp.status,cp.total_candidate_count,cp.suppressed_group_count,cp.taxonomy_version,ss.search_name FROM commercial_capability_packs cp JOIN commercial_saved_searches ss ON ss.id=cp.saved_search_id WHERE cp.commercial_manager_id=? ORDER BY cp.created_at DESC");$s->bind_param('i',$managerId);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}
require __DIR__.'/_layout_start.php';?>
<div class="cm-page-header"><div><span>Tender Evidence</span><h2>Capability Packs</h2><p>Generate and review anonymised tender capability evidence.</p></div><a class="cm-btn cm-btn--primary" href="<?= url('commercial_manager/saved_searches.php') ?>"><i class="fas fa-plus"></i> Generate From Saved Search</a></div>
<div class="cm-pack-grid"><?php foreach($rows as $r):?><article><i class="fas fa-file-shield"></i><span class="cm-status cm-status--<?= e(cm_status_class($r['status'])) ?>"><?= e(cm_label($r['status'])) ?></span><h3><?= e($r['pack_name']) ?></h3><p><?= e($r['search_name']) ?></p><div><span><?= number_format((int)$r['total_candidate_count']) ?> candidates</span><span><?= number_format((int)$r['suppressed_group_count']) ?> suppressed</span><span><?= e($r['taxonomy_version']) ?></span></div><a class="cm-btn cm-btn--secondary" href="<?= url('commercial_manager/pack_view.php?id='.(int)$r['id']) ?>">Open Pack <i class="fas fa-arrow-right"></i></a></article><?php endforeach;?></div>
<?php if(!$rows):?><div class="cm-card"><div class="cm-empty"><i class="fas fa-file-shield"></i><strong>No capability packs</strong><span>Generate one from a saved search.</span></div></div><?php endif;?>
<?php require __DIR__.'/_layout_end.php';?>